blocks.text:
.flex-container {
  display: flex;
  flex-direction: row;
}

  .flex-item {
  background-color: #f1f1f1;
  padding: 10px;

  font-size: 30px;
  text-align: center;
  width: 100%;
}

/*
  Make a one column-layout instead of three-column layout */
@media
  (max-width: 600px) {
  .flex-container {

  flex-direction: column;
  }
}

.flex-container {
  display: flex;
  flex-wrap: wrap;
}

.flex-item
  {
  background-color: #f1f1f1;
  padding: 10px;

  text-align: center;
  font-size: 30px;
  flex: 33.3%;
}

/*
  Make a one
  column-layout instead of a three-column layout */
@media (max-width: 600px)
  {
  .flex-item {
    flex: 100%;
  }
}
